const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7'); // You must include this line

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const geom = ee.Geometry.Rectangle({coords: [-150, -5, -90, 5], geodesic: false});
    const novStart = '2021-11-01';
    const novEnd = '2021-12-01';
    const climStartYear = 1982;
    const climEndYear = 2020;

    // 2. Data Acquisition & Check with fallback
    const datasetIds = ['NOAA/CDR/OISST/V2_1', 'NOAA/CDR/OISST/V2'];
    let chosenId = null;
    for (let id of datasetIds) {
      try {
        const tmpCol = ee.ImageCollection(id).select('sst');
        const s1 = await tmpCol.filterDate(novStart, novEnd).size().getInfo();
        const s2 = await tmpCol
          .filter(ee.Filter.calendarRange(11, 11, 'month'))
          .filter(ee.Filter.calendarRange(climStartYear, climEndYear, 'year'))
          .size()
          .getInfo();
        if (s1 > 0 && s2 > 0) {
          chosenId = id;
          break;
        }
      } catch (e) {
        // try next id
      }
    }
    if (!chosenId) {
      console.log('Dataset: None found');
      console.log('C1');
      return;
    }
    console.log(`Dataset: ${chosenId}`);

    const col = ee.ImageCollection(chosenId).select('sst');
    const colNov2021 = col.filterDate(novStart, novEnd);
    const colClim = col
      .filter(ee.Filter.calendarRange(11, 11, 'month'))
      .filter(ee.Filter.calendarRange(climStartYear, climEndYear, 'year'));

    const nNov = await colNov2021.size().getInfo();
    const nClim = await colClim.size().getInfo();
    console.log(`Nov-2021 Images: ${nNov}`);
    console.log(`Clim Nov Images: ${nClim}`);
    if (nNov === 0 || nClim === 0) {
      console.log('C1');
      return;
    }

    // 3. Processing: mean images and valid pixel counts
    const imgNov = colNov2021.mean().clip(geom);
    const imgClim = colClim.mean().clip(geom);

    const countNovDict = await imgNov.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: 25000,
      maxPixels: 1e9,
    }).getInfo();
    const countClimDict = await imgClim.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: 25000,
      maxPixels: 1e9,
    }).getInfo();

    const pxNov = (countNovDict && countNovDict.sst) ? countNovDict.sst : 0;
    const pxClim = (countClimDict && countClimDict.sst) ? countClimDict.sst : 0;
    console.log(`Valid pixels Nov-2021: ${pxNov}`);
    console.log(`Valid pixels Clim: ${pxClim}`);
    if (pxNov === 0 || pxClim === 0) {
      console.log('C2');
      return;
    }

    // 4. Calculation: regional mean SSTs
    const meanNovDict = await imgNov.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: 25000,
      maxPixels: 1e9,
    }).getInfo();
    const meanClimDict = await imgClim.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: 25000,
      maxPixels: 1e9,
    }).getInfo();

    const meanNov = meanNovDict ? meanNovDict.sst : null;
    const meanClim = meanClimDict ? meanClimDict.sst : null;

    if (
      meanNov === null || meanClim === null ||
      isNaN(meanNov) || isNaN(meanClim) ||
      Math.abs(meanNov) > 1000 || Math.abs(meanClim) > 1000
    ) {
      console.log('C3');
      return;
    }

    const diff = meanNov - meanClim;
    console.log(`Nov-2021 mean SST: ${meanNov.toFixed(2)}`);
    console.log(`Clim Nov mean SST: ${meanClim.toFixed(2)}`);
    console.log(`Delta (2021 - Clim): ${diff.toFixed(2)}`);

    // 5. Final Answer
    if (diff < 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${String(err).substring(0, 180)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
